window.blogDetail = {"blogId":1472176694,"blogType":3,"pubTime":"2016-08-26 09:58","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"椰影婆娑话琼州（1）","commentNum":0,"effect1":8454656,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"对三亚的映象源于初中地理课本上的插图：大人和小孩在沙滩上追逐嬉戏，金灿灿的阳光洒在白色的沙滩上，一副春意融融的景象。后来听了那一首《请到天涯海角来》，对这座城市才有了一丝心动。这之后，在高中学苏轼生平时，才知道海南原来是古代流放官员之地。当时怎样也无法将这风光迷人的地方与蛮荒之地联系起来。所幸，今年夏天，我去三亚城游玩了一番，领略了热带风情。同时也揭开了心中的谜团。<br/>这次琼州之行，对我来说...","artype":1,"arUins":"","blogid":1472176694,"voteids":0,"pubtime":1472176694,"replynum":0,"category":"个人日记","effect":8454656,"exblogtype":3,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":81177,"lp_style":16843520,"lp_flag":0,"lp_topvalue":0,"orguin":619774944,"orgblogid":1472176694,"mention_uins":[],"attach":[],"comments":[],"html":"","custom_title":"椰影婆娑话琼州（1）","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1472176694"}